always_comb
  case (req)
    2'b01: gnt = 2'b01;
    2'b10: gnt = 2'b10;
    // 2'b00 and 2'b11 unhandled — gnt undefined
  endcase

fix_replacement:
always_comb begin
  gnt = 2'b00;  // Default: no grant
  case (req)
    2'b01: gnt = 2'b01;
    2'b10: gnt = 2'b10;
    2'b11: gnt = 2'b01;   // Both request: grant lower-indexed master
    default: gnt = 2'b00;
  endcase
end
